{
  "criteria": [
    {
      "id": "task-points",
      "score": 28,
      "max": 30,
      "comment": "All four points are covered: your name, where you live, where you work, and what you like doing. «В компания» communicates the workplace, though it is vague."
    },
    {
      "id": "task-length",
      "score": 5,
      "max": 15,
      "comment": "There are four sentences of content; «Пока» is a closing, not a fifth sentence. The task requires at least ten sentences and 2–5 questions, but there are no questions."
    },
    {
      "id": "letter-form",
      "score": 5,
      "max": 10,
      "comment": "The information follows a natural order, and «Пока» works as an informal closing. A greeting and signature are missing."
    },
    {
      "id": "vocabulary",
      "score": 19,
      "max": 20,
      "comment": "The everyday words are appropriate for A1 and express the intended meaning. The letter uses a limited range, but simple vocabulary is sufficient here."
    },
    {
      "id": "grammar",
      "score": 17.5,
      "max": 25,
      "comment": "The meaning remains clear, but several forms need correction: «с моя невеста», «Я работать», «в компания» and «читать книга»."
    }
  ],
  "corrected": "Меня зовут Митч. Я живу в Колорадо с моей невестой. Я работаю в компании. Я люблю читать книги. Пока.",
  "changes": [
    {
      "before": "с моя невеста",
      "after": "с моей невестой",
      "explanation": "The preposition «с» takes the instrumental case here; the possessive and noun must agree."
    },
    {
      "before": "Я работать",
      "after": "Я работаю",
      "explanation": "Use the first-person present-tense verb form after «я», not the infinitive."
    },
    {
      "before": "в компания",
      "after": "в компании",
      "explanation": "Use the prepositional case after «в» when saying where you work."
    },
    {
      "before": "читать книга",
      "after": "читать книги",
      "explanation": "The object of «читать» takes the accusative case; «книги» is the natural plural form for books in general."
    }
  ],
  "tips": [
    "Count your sentences before finishing: this task needs at least ten.",
    "Add 2–5 questions to your friend, plus a greeting and your signature.",
    "Practise present-tense verb forms and cases after «с» and «в»."
  ]
}
